//! Every server packet type must encode byte-for-byte as Archipelago does.
//!
//! Equivalent JSON is not enough. Key order, the `"class"` tags, compact
//! separators and non-ASCII passthrough are all observable on the wire, and a
//! client that caches or hashes a payload would notice a difference that a
//! semantic comparison would wave through.
//!
//! The reference bytes are committed in `vectors.txt`, generated by
//! `tools/gen-protocol-vectors.py`, so this runs without Python.

use pahoa_proto::server::*;
use pahoa_proto::types::*;
use pahoa_proto::{ServerPacket, encode};
use serde_json::{Map, Value, json};
use std::collections::BTreeMap;

const VECTORS: &str = include_str!("vectors.txt");

fn expected(case: &str) -> &'static str {
    for line in VECTORS.lines() {
        if line.starts_with('#') {
            continue;
        }
        if let Some((name, json)) = line.split_once('\t')
            && name == case
        {
            return json;
        }
    }
    panic!("no vector named {case:?} in vectors.txt");
}

/// Encode a single packet as it appears inside a frame (frames are arrays, so
/// strip the brackets to compare one packet at a time).
fn one(p: ServerPacket) -> String {
    let framed = encode(&[p]);
    framed[1..framed.len() - 1].to_string()
}

#[track_caller]
fn check(case: &str, p: ServerPacket) {
    assert_eq!(one(p), expected(case), "case {case}");
}

fn perms(collect: u8, release: u8, remaining: u8) -> BTreeMap<String, Permission> {
    BTreeMap::from([
        ("collect".to_string(), Permission::from(collect)),
        ("release".to_string(), Permission::from(release)),
        ("remaining".to_string(), Permission::from(remaining)),
    ])
}

#[test]
fn room_info() {
    check(
        "room_info",
        ServerPacket::RoomInfo(RoomInfo {
            version: Version::new(0, 6, 8),
            generator_version: Version::new(0, 6, 4),
            tags: vec!["AP".into()],
            password: true,
            permissions: perms(0, 7, 2),
            hint_cost: 10,
            location_check_points: 1,
            games: vec!["Archipelago".into(), "Timespinner".into()],
            datapackage_checksums: BTreeMap::from([
                ("Archipelago".to_string(), "abc123".to_string()),
                ("Timespinner".to_string(), "def456".to_string()),
            ]),
            seed_name: "12345678901234567890".into(),
            time: 1700000000.5,
        }),
    );
}

#[test]
fn connection_refused() {
    check(
        "connection_refused",
        ServerPacket::ConnectionRefused(ConnectionRefused {
            errors: vec![
                ConnectionRefusedReason::InvalidSlot,
                ConnectionRefusedReason::InvalidPassword,
            ],
        }),
    );
}

#[test]
fn connected() {
    check(
        "connected",
        ServerPacket::Connected(Box::new(Connected {
            team: 0,
            slot: 3,
            players: vec![
                NetworkPlayer {
                    team: 0,
                    slot: 1,
                    alias: "Alice".into(),
                    name: "Alice".into(),
                },
                NetworkPlayer {
                    team: 0,
                    slot: 2,
                    alias: "Bobby".into(),
                    name: "Bob".into(),
                },
            ],
            missing_locations: vec![10, 20, 30],
            checked_locations: vec![1, 2],
            slot_info: BTreeMap::from([
                (
                    "1".to_string(),
                    NetworkSlot {
                        name: "Alice".into(),
                        game: "Timespinner".into(),
                        slot_type: 1,
                        group_members: vec![],
                    },
                ),
                (
                    "2".to_string(),
                    NetworkSlot {
                        name: "Link".into(),
                        game: "Archipelago".into(),
                        slot_type: 2,
                        group_members: vec![1, 3],
                    },
                ),
            ]),
            hint_points: 42,
            slot_data: Some(
                serde_json::value::to_raw_value(&json!({"nested": {"a": [1, 2, 3]}, "flag": true}))
                    .unwrap(),
            ),
        })),
    );
}

#[test]
fn connected_omits_slot_data_entirely_when_not_requested() {
    check(
        "connected_no_slot_data",
        ServerPacket::Connected(Box::new(Connected {
            team: 0,
            slot: 1,
            players: vec![],
            missing_locations: vec![],
            checked_locations: vec![],
            slot_info: BTreeMap::new(),
            hint_points: 0,
            slot_data: None,
        })),
    );
}

