#[test]
fn room_update_sends_only_what_changed() {
    check(
        "room_update_partial",
        ServerPacket::RoomUpdate(Box::new(RoomUpdate {
            hint_points: Some(12),
            ..Default::default()
        })),
    );
    check(
        "room_update_checked",
        ServerPacket::RoomUpdate(Box::new(RoomUpdate {
            checked_locations: Some(vec![7, 8, 9]),
            hint_points: Some(3),
            ..Default::default()
        })),
    );
}

