#[test]
fn invalid_packet() {
    check(
        "invalid_packet_cmd",
        ServerPacket::InvalidPacket(InvalidPacket {
            problem_type: "cmd".into(),
            original_cmd: None,
            text: "Unknown command Nonsense".into(),
        }),
    );
    check(
        "invalid_packet_args",
        ServerPacket::InvalidPacket(InvalidPacket {
            problem_type: "arguments".into(),
            original_cmd: Some("LocationChecks".into()),
            text: "locations must be a list of integers".into(),
        }),
    );
}

/// The echo replies. These are the strongest test in the file: they only match
/// if the request map is mutated in place, keeping `cmd` where the client put
/// it and carrying unknown keys through untouched.
#[test]
fn retrieved_echoes_the_request() {
    let mut req = Map::new();
    req.insert("cmd".into(), Value::String("Get".into()));
    req.insert("keys".into(), json!(["a", "b"]));
    req.insert("client_tag".into(), json!(7));

    check(
        "retrieved",
        ServerPacket::echo(req, "Retrieved", &[("keys", json!({"a": 1, "b": null}))]),
    );
}

#[test]
fn set_reply_appends_after_the_request_fields() {
    let mut req = Map::new();
    req.insert("cmd".into(), Value::String("Set".into()));
    req.insert("key".into(), Value::String("counter".into()));
    req.insert("want_reply".into(), json!(true));

    check(
        "set_reply",
        ServerPacket::echo(
            req,
            "SetReply",
            &[
                ("original_value", json!(1)),
                ("value", json!(2)),
                ("slot", json!(3)),
            ],
        ),
    );
}

#[test]
fn bounced_is_the_bounce_with_cmd_rewritten() {
    let mut req = Map::new();
    req.insert("cmd".into(), Value::String("Bounce".into()));
    req.insert("tags".into(), json!(["DeathLink"]));
    req.insert(
        "data".into(),
        json!({"time": 1700000000.5, "cause": "fell", "source": "Alice"}),
    );

    check("bounced", ServerPacket::echo(req, "Bounced", &[]));
}

#[test]
fn hint_values_carry_their_class_tag() {
    // Hint is only ever sent, never accepted, but it still has to serialize
    // with its tag and an integer status.
    let h = Hint {
        receiving_player: 1,
        finding_player: 2,
        location: 3,
        item: 4,
        found: false,
        entrance: String::new(),
        item_flags: 1,
        status: HintStatus::Priority,
    };
    let mut req = Map::new();
    req.insert("cmd".into(), Value::String("PrintJSON".into()));
    req.insert("data".into(), json!([{"text": "x"}]));
    req.insert("type".into(), Value::String("Hint".into()));
    req.insert("extra_hint".into(), serde_json::to_value(&h).unwrap());

    check("hint_value", ServerPacket::Echo(req));
}

#[test]
fn every_vector_is_exercised() {
    // A vector nobody checks is a test that silently stopped running.
    let cases: Vec<&str> = VECTORS
        .lines()
        .filter(|l| !l.starts_with('#') && !l.trim().is_empty())
        .filter_map(|l| l.split_once('\t').map(|(n, _)| n))
        .collect();
    assert_eq!(cases.len(), 19, "vector count changed: {cases:?}");
}
